import gsap from"gsap/all";import ScrollTrigger from"gsap/ScrollTrigger";export function circleGallery(){const vw=window.innerWidth,vh=window.innerHeight,rx=.34*vw,rz=500,tiltY=vw<=768?80:180,entryAngle=Math.PI/2,offX=.85*vw,cgPhrase=document.getElementById("cg_phrase");function splitWords(el){const text=el.innerHTML,temp=document.createElement("div");function walk(node){if(3===node.nodeType){const words=node.textContent.split(/(\s+)/),frag=document.createDocumentFragment();words.forEach(word=>{if(word.trim()){const span=document.createElement("span");span.className="word",span.textContent=word,frag.appendChild(span)}else frag.appendChild(document.createTextNode(word))}),node.parentNode.replaceChild(frag,node)}else[...node.childNodes].forEach(walk)}temp.innerHTML=text,walk(temp),el.innerHTML=temp.innerHTML}splitWords(cgPhrase);const cgPhraseWords=gsap.utils.toArray("#cg_phrase .word");function getPos(t){if(t<=.12){const p=t/.12;return{x:-offX*(1-p),y:tiltY,z:rz*p,rotY:0}}if(t<=.88){const p=(t-.12)/.76,angle=entryAngle-p*Math.PI*2,x=Math.cos(angle)*rx,z=Math.sin(angle)*rz;return{x:x,y:z/rz*tiltY,z:z,rotY:p*Math.PI*2}}const p=(t-.88)/.12;return{x:offX*p,y:tiltY,z:rz*(1-p),rotY:2*Math.PI}}function buildSlices(){const SLICES=10,imgW=Math.min(Math.max(120,.14*vw),175),imgH=2*imgW/3,orbitR=(rx+rz)/2,bendRad=imgW/orbitR,cylR=orbitR,sliceW=imgW/10,totalBendDeg=180*bendRad/Math.PI,stepDeg=totalBendDeg/10;document.querySelectorAll("img.cg_img").forEach(img=>{const src=img.src,wrapper=document.createElement("div");wrapper.className="cg_img";for(let s=0;s<10;s++){const sl=document.createElement("div");sl.className="cg_slice";const displayW=sliceW+1.5;sl.style.width=displayW+"px",sl.style.left="50%",sl.style.marginLeft=-displayW/2+"px",sl.style.backgroundImage=`url(${src})`,sl.style.backgroundSize=`${imgW}px ${imgH}px`,sl.style.backgroundPosition=`${-s*sliceW}px 0px`,sl.style.transformOrigin=`50% 50% ${-cylR}px`;const angle=(s-4.5)*stepDeg;sl.style.transform=`rotateY(${angle}deg)`,wrapper.appendChild(sl)}img.parentNode.replaceChild(wrapper,img)})}buildSlices();const cgImgs=gsap.utils.toArray(".cg_img");cgImgs.forEach(img=>{img.style.opacity="0"});const stagger=.09,count=cgImgs.length,totalRange=1+.09*(count-1);ScrollTrigger.create({trigger:"#circle_gallery",start:"top top",end:"bottom bottom",pin:"#circle_gallery_pin",onUpdate(self){const progress=self.progress;cgImgs.forEach((img,i)=>{const imgT=progress*totalRange-.09*i;if(imgT<=0||imgT>=1)return void(img.style.opacity="0");let alpha=1;imgT<.06?alpha=imgT/.06:imgT>.94&&(alpha=(1-imgT)/.06);const pos=getPos(imgT);img.style.transform=`translate3d(${pos.x}px,${pos.y}px,${pos.z}px)\n            rotateY(${180*pos.rotY/Math.PI}deg)`,img.style.opacity=alpha,img.style.zIndex=Math.round(pos.z+600)});const phraseStart=.25,phraseEnd=.75;if(progress<.25||progress>.75)return void(cgPhrase.style.opacity="0");const globalP=(progress-.25)/.5,yOffset=200*(.5-globalP);cgPhrase.style.transform=`translateY(${yOffset}px)`;const revealEnd=.4;cgPhraseWords.forEach((word,index)=>{if(globalP<.4){const revealP=globalP/.4,wordT=revealP*(cgPhraseWords.length+4)-index,wP=Math.max(0,Math.min(1,wordT/3));word.style.opacity=wP,word.style.filter=`blur(${8*(1-wP)}px)`}else word.style.opacity=1,word.style.filter="blur(0px)"});let alpha=1;globalP<.1?alpha=globalP/.1:globalP>.75&&(alpha=(1-globalP)/.25),cgPhrase.style.opacity=alpha}})}